let n = 1000; // number of dots 

let m = new Array(n); // make a new list of floating points 
let x = new Array(n);
let y = new Array(n);
let vx = new Array(n);
let vy = new Array(n);
let redchannel = new Array(n); 
let bluechannel = new Array(n);
let greenchannel = new Array(n);
let shape = new Array(n);

//::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::

function setup() {
	createCanvas(windowWidth, windowHeight);
	fill(0,10);
	reset();// running the reset when you click. 10000 random values being plugged in 
}

//::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::

function draw() {
	noStroke();
	fill(0,30);
	rect(0, 0, width, height); //  black background 

	for (let i = 0; i < n; i++) { // runs the loop 10,000 times
		let dx = (window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))) - x[i]; // distance from the mouse 
		let dy = (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))) - y[i];

		let d = sqrt(dx*dx + dy*dy); // calculating the distance between the points and the mouse 
		if (d < 1) d = 1; 

		let f = cos(d * 0.06) * m[i] / d*2; //decides if it gets closer or further from the mouse 

		vx[i] = vx[i] * 0.4 - f * dx; //changing the velcoity so it moves towards the ring 
		vy[i] = vy[i] * 0.2 - f * dy;
	}

	for (let i = 0; i < n; i++) {
		x[i] += vx[i];
		y[i] += vy[i];

		if (x[i] < 0) x[i] = width;
		else if (x[i] > width) x[i] = 0;

		if (y[i] < 0) y[i] = height;
		else if (y[i] > height) y[i] = 0;

		if (m[i] < 0) fill(bluechannel[i], greenchannel[i] , 255);
		else fill(255, bluechannel[i],redchannel[i]);

			if (shape[i] > 2) fill(bluechannel[i], greenchannel[i] , 255);
		else fill(255, bluechannel[i],redchannel[i]);



		if (shape[i] > 2)  rect(x[i], y[i],10,10);
else if (shape[i] > 1 && shape[i] <=2) rect(x[i],y[i],2,2);
else ellipse(x[i], y[i],10,10);



	}
}

