function reset() { // counter that counts up to n 
	for (let i = 0; i < n; i++) { // i = 0, i < 10,0000, i++ what to do after each loop. 
		m[i] = randomGaussian() * 8; // gaussian distribution is a bell curve. let of the mass 
		x[i] = random(width);
		y[i] = random(height);
		bluechannel[i] = random(255);
		redchannel[i] = random(255);
		greenchannel[i] = random(255); 
		shape [i] = random(0,3); 
	}
}

//::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::

function mousePressed() {
	reset();
}
